 "content": "def transform(grid):
    out = [row[:] for row in grid]
    marks = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if len(marks) < 2:
        return out

    def nearby_count(pos):
        r0, c0 = pos
        return sum(
            1 for r, row in enumerate(grid) for c, v in enumerate(row)
            if v != 0 and v != 5 and abs(r-r0) <= 3 and abs(c-c0) <= 4
        )

    # The 5 embedded in the colored pattern is the source; the isolated 5 is its destination.
    counts = [nearby_count(p) for p in marks]
    source_i = max(range(len(marks)), key=lambda i: counts[i])
    sr, sc = marks[source_i]
    targets = [p for i, p in enumerate(marks) if i != source_i]
    tr, tc = min(targets, key=lambda p: nearby_count(p))

    pattern = []
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value and (r, c) != (sr, sc) and abs(r-sr) <= 3 and abs(c-sc) <= 4:
                pattern.append((r-sr, c-sc, value))

    # Remove the destination marker, then reproduce the source pattern at that location.
    out[tr][tc] = 0
    for dr, dc, value in pattern:
        rr, cc = tr + dr, tc + dc
        if 0 <= rr < len(out) and 0 <= cc < len(out[0]):
            out[rr][cc] = value
    return out

